def correct_bracketing(brackets: str):
    opening_brackets = 0
    closing_brackets = 0

    for bracket in brackets:
        if bracket == "<":
            opening_brackets += 1
        elif bracket == ">":
            closing_brackets += 1

    if opening_brackets != closing_brackets:
        return False

    stack = []
    for bracket in brackets:
        if bracket == "<":
            stack.append(bracket)
        elif bracket == ">":
            if not stack:
                return False
            stack.pop()

    return len(stack) == 0
def correct_bracketing(brackets: str):
    if not brackets:
        return False

    open_count = 0
    close_count = 0

    for char in brackets:
        if char == '<':
            open_count += 1
        elif char == '>':
            close_count += 1

        if close_count > open_count:
            return False

    return open_count == close_count
